                pg_cut = *pg_s;
                pg::truncateUtf8(pg_cut, 29U);
                pg_s = &pg_cut;
                pg_len = (int64_t)pg_cut.size();
                pg::logf("GCRaidAskApply.SourceName: string cut to %u bytes (limit 29)", (unsigned)pg_len);
