        w.i32(this->foot_x_2);
        w.u16(this->foot_x_3);
        w.u32(this->face_id);
        w.u32(this->hair_id);
        w.u32(this->hair_color);
        w.i32(this->fashion_x);
        w.i32(this->fashion_x_2);
        w.i32(this->fashion_x_3);
        w.i32(this->fashion_x_4);
        w.u32(this->fashion_x_5);
        w.i32(this->anon1);
        w.i32(this->anon2);
        w.i32(this->anon3);
        w.u16(this->anon4);
        w.u16(this->anon5);
