bool GCTeamLeaderAskInvite::read(Reader& r) {
    if (!r.i32(this->source_guid)) return r.fail("short read", "GCTeamLeaderAskInvite.source_guid");
    if (!r.i32(this->dest_guid)) return r.fail("short read", "GCTeamLeaderAskInvite.dest_guid");
    if (!r.u8(this->n_source_name)) return r.fail("short read", "GCTeamLeaderAskInvite.n_source_name");
    if (!r.u8(this->n_dest_name)) return r.fail("short read", "GCTeamLeaderAskInvite.n_dest_name");
    if (((int64_t)this->n_source_name <= 30LL)) {
        {
            const int64_t pg_len = (int64_t)this->n_source_name;
            if (pg_len < 0) return r.fail("negative length", "GCTeamLeaderAskInvite.source_name");
            if (!r.str(this->source_name, (size_t)pg_len)) return r.fail("short read", "GCTeamLeaderAskInvite.source_name");
        }
    }
    if (((int64_t)this->n_dest_name <= 30LL)) {
        {
            const int64_t pg_len = (int64_t)this->n_dest_name;
            if (pg_len < 0) return r.fail("negative length", "GCTeamLeaderAskInvite.dest_name");
            if (!r.str(this->dest_name, (size_t)pg_len)) return r.fail("short read", "GCTeamLeaderAskInvite.dest_name");
        }
    }
    if (!r.i32(this->unknow_1)) return r.fail("short read", "GCTeamLeaderAskInvite.unknow_1");
    if (!r.i32(this->unknow_2)) return r.fail("short read", "GCTeamLeaderAskInvite.unknow_2");
    if (!r.i16(this->unknow_3)) return r.fail("short read", "GCTeamLeaderAskInvite.unknow_3");
    if (!r.i16(this->unknow_4)) return r.fail("short read", "GCTeamLeaderAskInvite.unknow_4");
    return true;
}

void GCTeamLeaderAskInvite::write(Writer& w) const {
    w.i32(this->source_guid);
    w.i32(this->dest_guid);
    w.u8(this->n_source_name);
    w.u8(this->n_dest_name);
    if (((int64_t)this->n_source_name <= 30LL)) {
        {
            int64_t pg_len = (int64_t)this->n_source_name;
            if (pg_len < 0) pg_len = 0;
            w.padded(this->source_name, (size_t)pg_len);
        }
    }
    if (((int64_t)this->n_dest_name <= 30LL)) {
        {
            int64_t pg_len = (int64_t)this->n_dest_name;
            if (pg_len < 0) pg_len = 0;
            w.padded(this->dest_name, (size_t)pg_len);
        }
    }
    w.i32(this->unknow_1);
    w.i32(this->unknow_2);
    w.i16(this->unknow_3);
    w.i16(this->unknow_4);
}

